\title{A Chain-Cover Lower Bound for the Boolean Lattice}
\author{Aristotle}
\date{2026-07-06}

\begin{document}
\maketitle

\begin{abstract}
We study the minimum number of chains required to cover the Boolean lattice
$\Bn$ of all subsets of an $n$-element set ordered by inclusion. A \emph{chain}
is a family of subsets totally ordered by inclusion; a family of chains
\emph{covers} the lattice if every subset belongs to at least one chain. Our
central result is a sharp lower bound: any covering family of chains must contain
at least $\bincentral$ chains. The proof specializes the ``easy'' direction of
Dilworth's theorem to the Boolean lattice and isolates a single structural
mechanism---the middle layer is an antichain of maximum size, and a chain meets
an antichain in at most one element. We complement the bound with a discussion of
its tightness via symmetric chain decompositions, a comparison against the weaker
counting bound $2^n/(n+1)$ that exposes a $\Theta(\sqrt n)$ multiplicative gap
governed by the central limit theorem, and generalizations to divisor lattices,
random sublattices, and applications to hierarchical key management.
\end{abstract}

\section{Introduction}

The Boolean lattice $\Bn$ is the partially ordered set whose elements are the
subsets of $[n] := \{1,2,\dots,n\}$ and whose order is set inclusion
$\subseteq$. It is arguably the most fundamental finite lattice: the free
distributive lattice on $n$ generators, the space of truth assignments to $n$
propositional variables, and the divisor lattice of any squarefree integer with
$n$ prime factors.

Two dual questions dominate its combinatorics. \emph{Antichains}: how large can a
family of pairwise-incomparable subsets be? \emph{Chains}: how few totally
ordered families are needed to account for all subsets? Sperner's theorem (1928)
answers the first: the largest antichain has size $\bincentral$, attained by the
middle layer. Dilworth's theorem (1950) links the two: the minimum number of
chains covering a finite poset equals its maximum antichain size. Together they
pin the chain-cover number of $\Bn$ at exactly $\bincentral$.

This paper gives a self-contained, elementary proof of the \emph{lower bound}
half of that statement, together with an account of its sharpness, a quantitative
comparison to a naive counting bound, and generalizations.

\section{Definitions}

Throughout, $n \ge 0$ and $[n] = \{1,\dots,n\}$; $2^{[n]}$ is the set of all
subsets of $[n]$, so $|2^{[n]}| = 2^n$.

\begin{definition}[Boolean lattice]
The \emph{Boolean lattice} $\Bn$ is the poset $(2^{[n]}, \subseteq)$.
\end{definition}

\begin{definition}[Chain]
A set $C \subseteq 2^{[n]}$ is a \emph{chain} if for all $s,t \in C$, either
$s \subseteq t$ or $t \subseteq s$.
\end{definition}

\begin{definition}[Antichain]
A set $A \subseteq 2^{[n]}$ is an \emph{antichain} if for all distinct
$s,t \in A$, neither $s \subseteq t$ nor $t \subseteq s$.
\end{definition}

\begin{definition}[Chain cover]
A family $\Cc$ of chains \emph{covers} $\Bn$ if every $s \in 2^{[n]}$ lies in some
$C \in \Cc$. The \emph{chain-cover number} is the least cardinality of a covering
family.
\end{definition}

\begin{definition}[Middle layer]
For $0 \le k \le n$, the $k$-th layer is $\{s \subseteq [n] : |s| = k\}$, of size
$\binom{n}{k}$. The \emph{middle layer} is
$\Mn := \{s \subseteq [n] : |s| = \lfloor n/2\rfloor\}$, with
$|\Mn| = \bincentral$.
\end{definition}

\section{Main result}

\subsection{Two structural lemmas}

\begin{lemma}[A chain meets an antichain at most once]\label{lem:meet}
Let $C$ be a chain and $A$ an antichain in $\Bn$. Then $|C \cap A| \le 1$.
\end{lemma}

\begin{proof}
Suppose $C \cap A$ contained distinct elements $a$ and $b$. As $a,b \in C$ and
$C$ is a chain, $a$ and $b$ are comparable. As $a,b \in A$, $a \ne b$, and $A$ is
an antichain, $a$ and $b$ are incomparable. This is a contradiction, so
$|C \cap A| \le 1$.
\end{proof}

\begin{lemma}[The middle layer is an antichain]\label{lem:mid}
$\Mn$ is an antichain, and $|\Mn| = \bincentral$.
\end{lemma}

\begin{proof}
Let $s,t \in \Mn$ be distinct; both have cardinality $\lfloor n/2\rfloor$. If
$s \subseteq t$ then, having equal finite cardinality, $s = t$, a contradiction;
by symmetry $t \subseteq s$ is impossible too. So $s,t$ are incomparable and
$\Mn$ is an antichain. Its size is the number of $\lfloor n/2\rfloor$-element
subsets of an $n$-set, namely $\bincentral$.
\end{proof}

\subsection{The lower bound}

\begin{theorem}[Chain-cover lower bound]\label{thm:main}
Let $\Cc$ be a finite family of chains in $\Bn$ such that every subset
$s \in 2^{[n]}$ belongs to some $C \in \Cc$. Then $|\Cc| \ge \bincentral$.
\end{theorem}

\begin{proof}
We bound $|\Mn|$ two ways. Since $\Cc$ covers every subset, it covers every
element of $\Mn$, so $\Mn \subseteq \bigcup_{C \in \Cc}(C \cap \Mn)$ and by
subadditivity
\[
  |\Mn| \le \sum_{C \in \Cc} |C \cap \Mn|.
\]
By Lemma~\ref{lem:mid}, $\Mn$ is an antichain, so Lemma~\ref{lem:meet} gives
$|C \cap \Mn| \le 1$ for each $C$, whence
$\sum_{C \in \Cc} |C \cap \Mn| \le |\Cc|$. Combining and using
Lemma~\ref{lem:mid},
\[
  \bincentral = |\Mn| \le \sum_{C \in \Cc} |C \cap \Mn| \le |\Cc|. \qedhere
\]
\end{proof}

\subsection{Tightness}

\begin{theorem}[The bound is attained]\label{thm:tight}
There exists a family of exactly $\bincentral$ chains covering $\Bn$;
consequently the chain-cover number equals $\bincentral$.
\end{theorem}

\begin{proof}[Proof sketch]
This is the existence of a \emph{symmetric chain decomposition} (SCD) of $\Bn$: a
partition of $2^{[n]}$ into chains, each passing through consecutive layers
symmetric about $n/2$. Encode each subset as a $\pm 1$ string and apply the
parenthesis-matching rule: match each $-1$ with the nearest unmatched preceding
$+1$; the unmatched symbols determine the chain, and toggling the first unmatched
symbol moves along it. Each chain contains exactly one middle-layer element, so
the number of chains equals $|\Mn| = \bincentral$. With Theorem~\ref{thm:main},
the chain-cover number is exactly $\bincentral$.
\end{proof}

\section{A quantitative comparison of lower bounds}

\begin{proposition}[Counting bound]\label{prop:count}
Every chain in $\Bn$ has at most $n+1$ elements, so any covering family has at
least $2^n/(n+1)$ chains.
\end{proposition}

\begin{proof}
Cardinalities strictly increase along a chain and lie in $\{0,\dots,n\}$, so a
chain has at most $n+1$ members. If $\Cc$ covers all $2^n$ subsets,
$|\Cc|\,(n+1) \ge 2^n$.
\end{proof}

\begin{proposition}[The antichain bound dominates by $\Theta(\sqrt n)$]
As $n \to \infty$,
\[
  \frac{\bincentral}{2^n/(n+1)} = (1+o(1))\sqrt{\tfrac{2}{\pi}}\,\sqrt{n},
\]
so on a logarithmic scale the bounds differ by $\tfrac12\log_2 n + O(1)$.
\end{proposition}

\begin{proof}
By Stirling, $\bincentral = (1+o(1))\,2^n\sqrt{2/(\pi n)}$. Dividing by
$2^n/(n+1)$ yields $(1+o(1))\sqrt{2n/\pi}$; taking $\log_2$ gives the stated
difference.
\end{proof}

The counting bound treats every chain as maximal (length $n+1$), but in an
optimal decomposition most chains are far shorter because the extreme layers are
thin. The gap is governed by the Gaussian spreading of the binomial
coefficients.

\section{Generalizations}

\paragraph{Divisor lattices.}
The divisor lattice of $N = p_1^{e_1}\cdots p_k^{e_k}$ under divisibility is
isomorphic to $\prod_{i=1}^k \{0,1,\dots,e_i\}$. Its largest antichain is the
middle-weight layer, whose size is the largest coefficient of
$\prod_{i=1}^k (1 + x + \cdots + x^{e_i})$; by the same argument the chain-cover
number equals this peak coefficient. For squarefree $N$ this recovers
$\binom{k}{\lfloor k/2\rfloor}$.

\paragraph{Random sublattices.}
Retaining each subset independently with probability $p$, the surviving middle
layer concentrates about $p\bincentral$, so the chain-cover number of the
retained poset is with high probability $(1+o(1))\,p\bincentral$.

\section{Applications to cryptography}

Hierarchical access-control systems assign each principal a set of permissions,
ordered by inclusion---precisely $\Bn$ for $n$ atomic permissions. A chain models
a linear clearance ladder, corresponding in key-management schemes to a single
linear key-derivation track. Theorem~\ref{thm:main} implies that no
key-management scheme can compress the permission lattice into fewer than
$\bincentral$ linear derivation tracks---a construction-independent floor,
growing nearly like $2^n/\sqrt n$, on the structural complexity of any
inclusion-based key hierarchy.

\section{Discussion and conclusion}

The value of Theorem~\ref{thm:main} lies in its economy: the lower-bound half of
Dilworth's theorem becomes a two-lemma argument in the Boolean setting. The bound
is sharp (Theorem~\ref{thm:tight}) and dominates the naive counting bound by a
$\sqrt n$ factor. It extends to divisor lattices, random sublattices, and the
analysis of cryptographic access hierarchies. Covering the Boolean lattice by
chains requires at least $\bincentral$ chains, because the middle layer is an
antichain of that size and each chain absorbs at most one of its members.

\end{document}

