"""Demo: the middle layer is a maximum antichain of size C(n, floor(n/2))."""
from itertools import combinations
from math import comb
from typing import FrozenSet, List


def middle_layer(n: int) -> List[FrozenSet[int]]:
    k = n // 2
    return [frozenset(c) for c in combinations(range(n), k)]


def comparable(s: FrozenSet[int], t: FrozenSet[int]) -> bool:
    return s <= t or t <= s


def is_antichain(family: List[FrozenSet[int]]) -> bool:
    return all(not comparable(a, b) for a, b in combinations(family, 2))


def main() -> None:
    for n in range(1, 8):
        M = middle_layer(n)
        print(f"n={n}: |M|={len(M)}  C(n,n/2)={comb(n, n//2)}  "
              f"antichain={is_antichain(M)}")


if __name__ == "__main__":
    main()

"""Demo: a symmetric chain decomposition covers B_n with exactly C(n,n/2) chains."""
from math import comb
from typing import Dict, FrozenSet, List, Tuple


def bracket_key(bits: Tuple[int, ...]) -> Tuple[int, ...]:
    stack: List[int] = []
    matched = set()
    for i, b in enumerate(bits):
        if b == 1:
            stack.append(i)
        elif stack:
            matched.add(stack.pop())
            matched.add(i)
    return tuple(bits[i] if i in matched else 0 for i in range(len(bits)))


def scd(n: int) -> List[List[FrozenSet[int]]]:
    groups: Dict[Tuple[int, ...], List[Tuple[int, ...]]] = {}
    for x in range(2 ** n):
        bits = tuple((x >> i) & 1 for i in range(n))
        groups.setdefault(bracket_key(bits), []).append(bits)
    chains = []
    for members in groups.values():
        members.sort(key=sum)
        chains.append([frozenset(i for i, v in enumerate(b) if v) for b in members])
    return chains


def main() -> None:
    for n in range(1, 8):
        chains = scd(n)
        covered = {s for c in chains for s in c}
        print(f"n={n}: chains={len(chains)}  bound={comb(n, n//2)}  "
              f"covers_all={len(covered) == 2 ** n}")


if __name__ == "__main__":
    main()

"""Demo: divisor-lattice chain-cover number = peak Gaussian-product coefficient."""
from math import comb
from typing import List, Tuple


def peak_coefficient(exponents: Tuple[int, ...]) -> Tuple[List[int], int]:
    poly: List[int] = [1]
    for e in exponents:
        factor = [1] * (e + 1)
        new = [0] * (len(poly) + len(factor) - 1)
        for i, a in enumerate(poly):
            for j, b in enumerate(factor):
                new[i + j] += a * b
        poly = new
    return poly, max(poly)


def main() -> None:
    for exps in [(2, 1, 3), (1, 1, 1, 1), (4,), (2, 2)]:
        poly, peak = peak_coefficient(exps)
        note = ""
        if all(e == 1 for e in exps):
            k = len(exps)
            note = f"  (squarefree: C({k},{k//2})={comb(k, k//2)})"
        print(f"exponents={exps}: coeffs={poly} -> chain-cover={peak}{note}")


if __name__ == "__main__":
    main()

